"""Actual pinned-parser completed-image contracts; generated bytes only."""
import json
from pathlib import Path
import struct
import xml.etree.ElementTree as ET

import pytest
import cli_map_editor as editor
import transactional_batch as batch
from test_batch_plan_cli import _cli, _plan
from test_editor_exporter_contract import make_session, TABLE_OFFSET

FACTOR_OFFSET = 0x90


def linked_fixture(tmp_path, alias=False):
    initial, _ = make_session(tmp_path)
    tree = ET.parse(initial.xdf_path)
    root = tree.getroot()
    for uid, title in [('0x30', 'Factor')] + ([('0x31', 'Factor alias')] if alias else []):
        scalar = ET.SubElement(root, 'XDFCONSTANT', uniqueid=uid)
        ET.SubElement(scalar, 'title').text = title
        ET.SubElement(scalar, 'EMBEDDEDDATA', mmedaddress='0x70',
                      mmedelementsizebits='16', mmedtypeflags='0x00')
        math = ET.SubElement(scalar, 'MATH', equation='X/10')
        ET.SubElement(math, 'VAR', id='X')
    math = root.find('./XDFTABLE/XDFAXIS[@id="z"]/MATH')
    math.set('equation', 'X*Y')
    ET.SubElement(math, 'VAR', id='Y', type='link', linkid='0x30')
    tree.write(initial.xdf_path, encoding='utf-8', xml_declaration=True)
    original = bytearray(Path(initial.bin_path).read_bytes())
    struct.pack_into('>H', original, FACTOR_OFFSET, 20)
    Path(initial.bin_path).write_bytes(original)
    session = editor.XDFBinSession(initial.xdf_path, initial.bin_path)
    assert session.load()
    assert session.read_table_data(session.tables[0])[0][0] == -8
    return session, bytes(original)


def test_actual_linked_dependency_later_change_is_refused(tmp_path, monkeypatch, capsys):
    session, before = linked_fixture(tmp_path)
    plan = _plan(tmp_path, session, [
        {'type': 'table', 'map': 'Scaled table', 'row': 1, 'col': 1,
         'value': -10, 'expected_raw': -4},
        {'type': 'scalar', 'map': 'Factor', 'value': 3, 'expected_raw': 20},
    ])
    out = tmp_path / 'out'
    assert _cli(monkeypatch, session, plan, '--autosave', '--output-dir',
                str(out), '--json') == 1
    result = json.loads(capsys.readouterr().out)
    assert 'conversion dependency changed' in result['error']
    assert not out.exists()
    assert Path(session.bin_path).read_bytes() == before


def test_actual_linked_dependency_first_uses_staged_value_and_full_bytes(tmp_path, monkeypatch, capsys):
    session, before = linked_fixture(tmp_path)
    plan = _plan(tmp_path, session, [
        {'type': 'scalar', 'map': 'Factor', 'value': 3, 'expected_raw': 20},
        {'type': 'table', 'map': 'Scaled table', 'row': 1, 'col': 1,
         'value': -10, 'expected_raw': -4},
    ])
    out = tmp_path / 'out'
    monkeypatch.setattr(editor, '_timestamp', lambda: 'fixed')
    assert _cli(monkeypatch, session, plan, '--autosave', '--output-dir',
                str(out), '--json') == 0
    result = json.loads(capsys.readouterr().out)
    expected = bytearray(before)
    struct.pack_into('>H', expected, FACTOR_OFFSET, 30)
    # -10 / 3 quantizes to -3, decoded using the completed factor as -9.
    struct.pack_into('<h', expected, TABLE_OFFSET, -3)
    saved = Path(result['saved_bin'])
    assert saved.read_bytes() == bytes(expected)
    assert len(list(out.glob('*.bin'))) == 1
    assert Path(session.bin_path).read_bytes() == before
    assert result['changed_byte_count'] == 2
    loaded = editor.XDFBinSession(session.xdf_path, str(saved))
    assert loaded.load()
    assert loaded.read_table_data(loaded.tables[0])[0][0] == -9


def test_actual_parser_alias_storage_collision_is_refused(tmp_path, monkeypatch, capsys):
    session, before = linked_fixture(tmp_path, alias=True)
    plan = _plan(tmp_path, session, [
        {'type': 'scalar', 'map': 'Factor', 'value': 3},
        {'type': 'scalar', 'map': 'Factor alias', 'value': 4},
    ])
    out = tmp_path / 'out'
    assert _cli(monkeypatch, session, plan, '--autosave', '--output-dir',
                str(out), '--json') == 1
    assert 'Conflicting XDF writes' in json.loads(capsys.readouterr().out)['error']
    assert not out.exists()
    assert Path(session.bin_path).read_bytes() == before


@pytest.mark.parametrize('changed', ['bin', 'xdf', 'plan'])
def test_actual_parser_source_race_rolls_back_session(tmp_path, monkeypatch, capsys, changed):
    session, before = linked_fixture(tmp_path)
    plan = _plan(tmp_path, session, [
        {'type': 'scalar', 'map': 'Scaled scalar', 'value': -8.2},
    ])
    target = {'bin': Path(session.bin_path), 'xdf': Path(session.xdf_path),
              'plan': plan}[changed]
    target_before = target.read_bytes()
    original_verify = batch._verify_final
    actual_class = editor.XDFBinSession
    seen = []

    def capture(*args):
        value = actual_class(*args)
        seen.append(value)
        return value

    def tamper(*args):
        value = original_verify(*args)
        target.write_bytes(target_before + b'\n')
        return value

    monkeypatch.setattr(editor, 'XDFBinSession', capture)
    monkeypatch.setattr(batch, '_verify_final', tamper)
    out = tmp_path / 'out'
    assert _cli(monkeypatch, session, plan, '--autosave', '--output-dir',
                str(out), '--json') == 1
    assert 'changed while staging' in json.loads(capsys.readouterr().out)['error']
    assert len(seen) == 1
    assert bytes(seen[0].bin_data) == before
    assert seen[0].changes == []
    assert not out.exists()
    assert Path(session.bin_path).read_bytes() == (before + b'\n' if changed == 'bin' else before)
